"""Phase 4: platform tests for the eval kit generated by the current template.

The generated evaluator runs only in subprocesses, with golden_path import-
blocked (see conftest.blocked_env). The eval kit's own regression tests live
in the generated project's tests/test_evals.py; this file adds platform-level
evidence: schema snapshots, cross-process determinism, and a real behavioral
false positive of the fake adapter.
"""

from __future__ import annotations

import getpass
import hashlib
import json
import re
import subprocess
import sys
from pathlib import Path

import pytest
import yaml
from jsonschema import Draft202012Validator

from conftest import only_record
from golden_path import scaffold

CAPABILITY = "eval-demo"

# A real false positive of the fake's toy substring rule ("auth" in a path ->
# high risk). Deliberately NOT part of the default suite and NOT fixed in the
# fake: it is evidence that deterministic behavior can still be wrong.
AUTHORS_FALSE_POSITIVE_CASE = {
    "id": "docs-only-authors-update",
    "kind": "expect_success",
    "property": "A documentation-only change to the AUTHORS file is not classified as high risk.",
    "input": {
        "change_id": "CHG-2009",
        "title": "Add new contributor to AUTHORS",
        "summary": "Adds a new contributor name to the AUTHORS file. No code changes.",
        "files_changed": ["AUTHORS.md"],
    },
    "expect": {"risk_level_in": ["low"], "open_questions": "empty"},
}


@pytest.fixture
def project(tmp_path) -> Path:
    destination, _ = scaffold.new_capability(CAPABILITY, tmp_path)
    return destination


def run_evaluator(project: Path, env: dict, **extra_env) -> subprocess.CompletedProcess:
    return subprocess.run(
        [sys.executable, "evals/evaluator.py"],
        cwd=project,
        env={**env, **extra_env},
        capture_output=True,
        text=True,
        check=False,
    )


def append_case(project: Path, case: dict) -> None:
    path = project / "evals" / "cases.yaml"
    suite = yaml.safe_load(path.read_text())
    suite["cases"].append(case)
    path.write_text(yaml.safe_dump(suite, sort_keys=False))


# --- contracts ----------------------------------------------------------------------


@pytest.mark.parametrize("name", ["eval-suite.schema.json", "eval-report.schema.json"])
def test_canonical_eval_schemas_are_valid_and_snapshotted_byte_for_byte(project, name):
    canonical = scaffold.LAB_ROOT / "schemas" / name
    Draft202012Validator.check_schema(json.loads(canonical.read_text()))
    assert (project / "platform" / name).read_bytes() == canonical.read_bytes()


def test_generated_suite_validates_against_canonical_suite_schema(project):
    schema = json.loads((scaffold.LAB_ROOT / "schemas" / "eval-suite.schema.json").read_text())
    suite = yaml.safe_load((project / "evals" / "cases.yaml").read_text())
    assert list(Draft202012Validator(schema).iter_errors(suite)) == []
    kinds = [case["kind"] for case in suite["cases"]]
    assert kinds.count("expect_success") == 5
    assert kinds.count("expect_input_rejected") == 2
    assert kinds.count("expect_output_rejected") == 1


def test_scripted_case_declares_one_response_per_budgeted_request(project):
    manifest = yaml.safe_load((project / "capability.yaml").read_text())
    suite = yaml.safe_load((project / "evals" / "cases.yaml").read_text())
    scripted = [c for c in suite["cases"] if c["kind"] == "expect_output_rejected"]
    budget = manifest["spec"]["budgets"]["max_model_requests"]
    assert [len(c["model_script"]) for c in scripted] == [budget]


# --- the generated evaluator, golden_path blocked -------------------------------------


def test_evaluator_passes_gate_and_report_validates(project, blocked_env):
    completed = run_evaluator(project, blocked_env)
    assert completed.returncode == 0, completed.stderr
    report = json.loads(completed.stdout)
    schema = json.loads((scaffold.LAB_ROOT / "schemas" / "eval-report.schema.json").read_text())
    assert list(Draft202012Validator(schema).iter_errors(report)) == []
    assert report["summary"] == {
        "total": 8,
        "passed": 8,
        "failed": 0,
        "observed_pass_rate": 1.0,
        "required_pass_rate": 1.0,
        "gate_passed": True,
    }
    assert report["capability"]["template_version"] == scaffold.TEMPLATE_VERSION
    assert only_record(completed.stderr, "eval_summary")["gate_passed"] is True


def test_report_is_byte_identical_across_processes_and_hash_seeds(project, blocked_env):
    first = run_evaluator(project, blocked_env, PYTHONHASHSEED="0")
    second = run_evaluator(project, blocked_env, PYTHONHASHSEED="1")
    assert first.returncode == second.returncode == 0
    assert first.stdout == second.stdout


def test_report_is_stable_across_project_locations(tmp_path, blocked_env):
    reports = []
    for parent in ("a", "b/nested"):
        (tmp_path / parent).mkdir(parents=True)
        destination, _ = scaffold.new_capability(CAPABILITY, tmp_path / parent)
        reports.append(run_evaluator(destination, blocked_env).stdout)
    assert reports[0] == reports[1]


def test_report_keys_sorted_and_suite_hash_matches_bytes(project, blocked_env):
    stdout = run_evaluator(project, blocked_env).stdout
    report = json.loads(stdout)
    assert stdout == json.dumps(report, indent=2, sort_keys=True) + "\n"
    assert report["suite"]["sha256"] == hashlib.sha256((project / "evals" / "cases.yaml").read_bytes()).hexdigest()


def test_report_has_no_machine_specific_or_nondeterministic_values(project, blocked_env):
    stdout = run_evaluator(project, blocked_env).stdout
    for value in (str(project), str(Path.home()), str(scaffold.LAB_ROOT), getpass.getuser()):
        assert value not in stdout
    assert not re.search(r"\d{4}-\d{2}-\d{2}", stdout)
    assert not re.search(r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-", stdout)
    for forbidden_key in ("timestamp", "duration", "latency", "tokens", "cost", "message"):
        assert f'"{forbidden_key}' not in stdout


def test_report_never_contains_raw_model_output(project, blocked_env):
    stdout = run_evaluator(project, blocked_env).stdout
    assert "This change touches" not in stdout  # fake explanation prefix
    assert "The change looks low risk." not in stdout  # scripted raw response


# --- a real behavioral false positive -----------------------------------------------------


def test_authors_file_false_positive_fails_case_and_gate(project, blocked_env):
    append_case(project, AUTHORS_FALSE_POSITIVE_CASE)
    completed = run_evaluator(project, blocked_env)
    assert completed.returncode == 1
    report = json.loads(completed.stdout)
    case = next(c for c in report["cases"] if c["id"] == "docs-only-authors-update")
    assert case["passed"] is False
    assert case["outcome"] == {"result": "succeeded", "model_requests_used": 1}
    risk = next(check for check in case["checks"] if check["name"] == "risk_level_in")
    assert risk == {"name": "risk_level_in", "expected": ["low"], "observed": "high", "passed": False}
    assert report["summary"]["observed_pass_rate"] == 8 / 9
    assert report["summary"]["gate_passed"] is False
    summary = only_record(completed.stderr, "eval_summary")
    assert (summary["passed"], summary["total"], summary["gate_passed"]) == (8, 9, False)


# --- malformed suite ----------------------------------------------------------------------


def test_malformed_suite_exits_3_with_no_partial_report(project, blocked_env):
    path = project / "evals" / "cases.yaml"
    suite = yaml.safe_load(path.read_text())
    suite["cases"] = [c for c in suite["cases"] if c["kind"] == "expect_success"]
    path.write_text(yaml.safe_dump(suite, sort_keys=False))
    completed = run_evaluator(project, blocked_env)
    assert completed.returncode == 3
    assert completed.stdout == ""
    assert only_record(completed.stderr, "error")["error"] == "EvalSuiteError"


def test_declared_tools_abort_evaluation_with_exit_3(project, blocked_env):
    manifest = project / "capability.yaml"
    manifest.write_text(manifest.read_text().replace("tools: []", "tools: [search_docs]"))
    completed = run_evaluator(project, blocked_env)
    assert completed.returncode == 3
    assert completed.stdout == ""
